   array['stage', 'move', 'variable', 'score', 'variant'], 40, 1),
  ('blockly', 'blk-g2-fall-u2', 'blk-g2-fall', '随机节奏与计分',
   '用固定伪随机节奏排布地鼠与障碍，在躲避、接取和扣分中完成综合挑战。', 'stage',
   array['stage', 'collision', 'score', 'lives', 'variant'], 40, 2),
  ('blockly', 'blk-g2-spring-u1', 'blk-g2-spring', '克隆与子弹变体',
   '从单发克隆到双重火力、三向散弹和定位星星驱动的折线追踪弹。', 'stage',
   array['stage', 'clone', 'projectile', 'spread', 'tracking'], 40, 1),
  ('blockly', 'blk-g2-spring-u2', 'blk-g2-spring', '塔防与怪物编队',
   '用单怪、重甲怪和多怪重叠编队练习嵌套判断，并让两座塔协同防守。', 'stage',
   array['stage', 'clone', 'tower', 'monster', 'nested'], 40, 2)
on conflict (module_id, unit_id) do update set
  term_id = excluded.term_id,
  title = excluded.title,
  summary = excluded.summary,
  scene_form = excluded.scene_form,
  knowledge_tags = excluded.knowledge_tags,
  level_cap = excluded.level_cap,
  sort_order = excluded.sort_order,
  updated_at = now();

