  "scene_type": "stage",
  "scene": {
    "backdrop": "night",
    "stage_size": {
      "width": 480,
      "height": 360
    },
    "sprites": [
      {
        "id": "player",
        "asset": "ship",
        "x": 40,
        "y": 300,
        "direction": 90,
        "size": 100,
        "collectible": false
      },
      {
        "id": "enemy-1",
        "asset": "enemy",
        "x": 67,
        "y": 200,
        "direction": 0,
        "size": 100,
        "collectible": true
      },
      {
        "id": "enemy-2",
        "asset": "enemy",
        "x": 85,
        "y": 140,
        "direction": 0,
        "size": 100,
        "collectible": true
      }
    ],
    "clones": [
      {
        "id": "bullet",
        "asset": "bullet",
        "spawn": {
          "x": "self",
          "y": "self"
        },
        "lifetime_steps": 45,
        "size": 50,
        "direction": 0
      }
    ],
    "variables": [
      {
        "id": "score",
        "name": "score",
        "initial": 0,
        "scope": "global"
      }
    ],
    "broadcasts": [],
    "initial_scripts": []
  },
  "available_blocks": [
    {
      "type": "move_steps",
      "label": "移动",
      "category": "动作",
      "kind": "action",
      "args": [
        {
          "name": "steps",
          "label": "步数",
          "type": "number",
          "default": 10,
          "min": -100,
          "max": 100,
          "step": 1
        }
      ]
    },
    {
      "type": "set_variable",
      "label": "设置变量",
      "category": "变量",
      "kind": "action",
      "args": [
        {
          "name": "variable_id",
          "label": "变量",
          "type": "variable",
          "default": "score"
        },
        {
          "name": "value",
          "label": "设为",
          "type": "number",
          "default": 0,
          "min": -100,
          "max": 100,
          "step": 1
        }
      ]
    },
    {
      "type": "change_variable",
      "label": "变量增加",
      "category": "变量",
      "kind": "action",
      "args": [
        {
          "name": "variable_id",
          "label": "变量",
          "type": "variable",
          "default": "score"
        },
        {
          "name": "value",
          "label": "增加",
          "type": "number",
          "default": 1,
          "min": -100,
          "max": 100,
          "step": 1
        }
      ]
    },
    {
      "type": "if_touching",
      "label": "如果碰到",
      "category": "控制",
      "kind": "control",
      "args": [
        {
          "name": "target_sprite_id",
          "label": "精灵",
          "type": "select",
          "default": "enemy-1",
          "options": [
            {
              "value": "enemy-1",
              "label": "enemy-1"
            },
            {
              "value": "enemy-2",
              "label": "enemy-2"
            }
          ]
        }
      ]
    },
    {
      "type": "forever",
      "label": "无限循环",
      "category": "控制",
      "kind": "control",
      "args": []
    },
    {
      "type": "clone",
      "label": "克隆",
      "category": "控制",
      "kind": "control",
      "args": [
        {
          "name": "clone_id",
          "label": "克隆谁",
          "type": "select",
          "default": "bullet",
          "options": [
            {
              "value": "bullet",
              "label": "子弹"
            }
          ]
        }
      ]
    }
  ],
  "success_check": {
    "type": "all",
    "conditions": [
      {
        "type": "variable_value",
        "variable_id": "score",
        "op": "==",
        "value": 2
      },
      {
        "type": "sprite_hidden",
        "sprite_id": "enemy-1"
      },
      {
        "type": "sprite_hidden",
        "sprite_id": "enemy-2"
      }
    ]
  },
  "workspace": {
    "initial_blocks": [],
    "max_blocks": 15,
    "require_connected": false
  },
  "runtime": {
    "out_of_bounds": "blocked",
    "max_steps": 87,
    "stop_on_success": true,
    "move_duration_ms": 0
  },
  "hints": [
    {
      "trigger": "initial",
      "text": "放一块「无限循环」让角色每步走 9，再放一块「克隆」：克隆出来的角色里面也放「无限循环」，先「移动」往上飞，再放一个「如果碰到」，碰到敌人就「变量增加」1 分。",
      "focus": {
        "target": "block",
        "blockType": "clone"
      }
    },
    {
      "trigger": "not_completed",
      "text": "score 要正好等于 2：克隆体要一直往上飞，「如果碰到」要选对敌人，每中一次只加 1 分。",
      "focus": {
        "target": "block",
        "blockType": "clone"
      }
    }
  ],
  "completion": {
    "stars": 3,
    "success_text": "子弹全部命中！"
  },
  "intro_story": [
    {
      "type": "text",
      "speaker": "小精灵",
      "content": "欢迎回来！我们再试一个新本领。这一关的目标是：用克隆火力打中 2 个敌人，把 score 加到 2。"
    },
    {
      "type": "image_text",
      "image": "stage",
      "speaker": "小精灵",
      "content": "欢迎来到自由舞台！舞台上的角色会一直往一个方向走，不会撞墙转弯，所以我们要算好时间。"
    },
    {
      "type": "image_text",
      "image": "block_clone",
      "speaker": "小精灵",
      "content": "今天请「造出新角色」来帮忙：复制出一个一模一样的角色，让它自己跑你写在里面的积木。"
    },
    {
      "type": "image_text",
      "image": "block_clone",
      "speaker": "机器人",
      "content": "这一关真正要用的就是「克隆」。放一块「无限循环」让角色每步走 9，再放一块「克隆」：克隆出来的角色里面也放「无限循环」，先「移动」往上飞，再放一个「如果碰到」，碰到敌人就「变量增加」1 分。"
    },
    {
      "type": "text",
      "speaker": "小精灵",
      "content": "把积木拖到工作区，连好，再点「运行」，我就能走完啦！"
    }
  ],
  "review": {
    "question": "上一关我们学了「造出新角色」，还记得怎么用吗？",
    "answer": "复制出一个一模一样的角色，让它自己跑你写在里面的积木。",
    "hint": "上一关复制出了 1 种新角色，打掉了 2 个敌人，score 记成了 2 分。"
  }
}
  $body$::jsonb,
   true, now(), now(),
   'blk-g2-spring', 'blk-g2-spring-u1', 'stage', 'practice',
   array['stage', 'clone', 'collision', 'gradient-1', 'variant-4'], null,
   15, false)
on conflict (module_id, level_id) do update set
  sort_order = excluded.sort_order,
  title = excluded.title,
  goal = excluded.goal,
  body = excluded.body,
  published = excluded.published,
  term_id = excluded.term_id,
  unit_id = excluded.unit_id,
  scene_type = excluded.scene_type,
  level_type = excluded.level_type,
  knowledge_tags = excluded.knowledge_tags,
  milestone_badge = excluded.milestone_badge,
  estimated_minutes = excluded.estimated_minutes,
  is_placeholder = excluded.is_placeholder,
  updated_at = now();

