  "success_check": {
    "type": "all",
    "conditions": [
      {
        "type": "variable_value",
        "variable_id": "score",
        "op": "==",
        "value": 5
      },
      {
        "type": "sprite_hidden",
        "sprite_id": "enemy-1"
      },
      {
        "type": "sprite_hidden",
        "sprite_id": "enemy-2"
      },
      {
        "type": "sprite_hidden",
        "sprite_id": "enemy-3"
      },
      {
        "type": "sprite_hidden",
        "sprite_id": "enemy-4"
      },
      {
        "type": "sprite_hidden",
        "sprite_id": "enemy-5"
      }
    ]
  },
  "workspace": {
    "initial_blocks": [],
    "max_blocks": 35,
    "require_connected": false
  },
  "runtime": {
    "out_of_bounds": "blocked",
    "max_steps": 89,
    "stop_on_success": true,
    "move_duration_ms": 0
  },
  "hints": [
    {
      "trigger": "initial",
      "text": "用两块「无限循环」分别「克隆」普通弹和炮弹，两个循环会同时运行。每颗子弹里先「移动」，再「如果碰到」敌人，「变量增加」1 分。",
      "focus": {
        "target": "block",
        "blockType": "clone"
      }
    },
    {
      "trigger": "not_completed",
      "text": "score 要正好等于 5：两条发射程序都要保留，子弹碰到敌人后再加分。",
      "focus": {
        "target": "block",
        "blockType": "clone"
      }
    }
  ],
  "completion": {
    "stars": 3,
    "success_text": "子弹全部命中！"
  },
  "intro_story": [
    {
      "type": "text",
      "speaker": "小精灵",
      "content": "欢迎回来！我们再试一个新本领。这一关的目标是：用两种克隆火力打中 5 个敌人，把 score 加到 5。"
    },
    {
      "type": "image_text",
      "image": "stage",
      "speaker": "小精灵",
      "content": "欢迎来到自由舞台！舞台上的角色会一直往一个方向走，不会撞墙转弯，所以我们要算好时间。"
    },
    {
      "type": "image_text",
      "image": "block_clone",
      "speaker": "小精灵",
      "content": "今天请「双重火力」来帮忙：两种弹药同时出发，一路清理航线上的目标。"
    },
    {
      "type": "image_text",
      "image": "block_clone",
      "speaker": "机器人",
      "content": "这一关真正要用的就是「克隆」。用两块「无限循环」分别「克隆」普通弹和炮弹，两个循环会同时运行。每颗子弹里先「移动」，再「如果碰到」敌人，「变量增加」1 分。"
    },
    {
      "type": "text",
      "speaker": "小精灵",
      "content": "把积木拖到工作区，连好，再点「运行」，我就能走完啦！"
    }
  ],
  "review": {
    "question": "上一关我们学了「双重火力」，还记得怎么用吗？",
    "answer": "两种弹药同时出发，一路清理航线上的目标。",
    "hint": "上一关用了两种弹药，打掉 5 个敌人，score 记成 5 分。"
  }
}
